# Established size (about 1–2 years after planting), in metres: height for plants and furniture,
# longest side for hardscape (accent boulders). model file → (old size, new size).
# Only rows still at the old value change, so sizes the owner already edited are kept.
SIZES = {
    'heliconia_rostrata.glb': (0.5, 1.8),
    'plumeria_flower.glb': (0.5, 2.0),
    'strelitzia.glb': (1.0, 1.2),
    'banana_tree.glb': (3.2, 3.5),
    'christmas_palm.glb': (6.0, 4.0),
    'mossy_rock.glb': (0.4, 0.7),
    'volcanic_rock.glb': (0.4, 0.6),
    'blueish_river_rock.glb': (0.4, 0.6),
    'bamboo_bench.glb': (1.0, 0.8),
    'outdoor_bench.glb': (1.0, 0.25),   # the model is out of proportion: 0.25 m tall = a 1.7 m long bench
    'rocking_chair.glb': (1.5, 1.05),
}


def realistic_sizes(apps, schema_editor):
    InventoryItem = apps.get_model('library', 'InventoryItem')
    for model_file, (old, new) in SIZES.items():
        for item in InventoryItem.objects.filter(model_file=model_file):
            if abs((item.real_world_size or 0) - old) < 1e-6:
                item.real_world_size = new
                item.save(update_fields=['real_world_size'])
    # The model is a Christmas palm (Adonidia, "Bunga de China"), not a coconut (15 m+)
    InventoryItem.objects.filter(model_file='christmas_palm.glb', name='Coconut Tree').update(name='Christmas Palm')


def previous_sizes(apps, schema_editor):
    InventoryItem = apps.get_model('library', 'InventoryItem')
    for model_file, (old, new) in SIZES.items():
        InventoryItem.objects.filter(model_file=model_file, real_world_size=new).update(real_world_size=old)
    InventoryItem.objects.filter(model_file='christmas_palm.glb', name='Christmas Palm').update(name='Coconut Tree')


